pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    XBORNID c;

    function setUp() public {
        c = new XBORNID();
    }

    function _run(bool doCall) internal {
        vm.assume(doCall);
        bool reverted;
        try c.finishDistribution() {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted || c.distributionFinished());
    }

    function testFuzz_run(bool doCall) public {
        _run(doCall);
    }

    receive() external payable {}
}
